<?php
namespace App\Services;use App\Models\JobApplication;
class CandidateJobMatcher{public function analyze(JobApplication $application):array{$profile=$application->profile_snapshot['profile']??[];$job=$application->job;$skills=collect($profile['skills']??[])->map(fn($v)=>mb_strtolower(is_array($v)?($v['name']??''):(string)$v))->filter()->values();$text=mb_strtolower($job->title.' '.$job->summary.' '.$job->description.' '.implode(' ',$job->requirements??[]));$matched=$skills->filter(fn($skill)=>mb_strlen($skill)>1&&str_contains($text,$skill))->values();$skillScore=$skills->isEmpty()?0:min(45,(int)round($matched->count()/max(1,min(5,$skills->count()))*45));$title=mb_strtolower((string)($profile['professional_title']??''));$roleScore=$title&&collect(preg_split('/\s+/u',$title))->filter(fn($w)=>mb_strlen($w)>3&&str_contains($text,$w))->isNotEmpty()?20:0;$modalities=collect($profile['preferred_modalities']??[]);$modalityScore=$modalities->isEmpty()||$modalities->contains($job->modality)?10:0;$locations=collect($profile['preferred_provinces']??[]);$locationScore=$locations->isEmpty()||$locations->contains($job->location)?10:0;$experienceScore=count($profile['experience']??[])>0?10:0;$educationScore=count($profile['education']??[])>0?5:0;$score=min(100,$skillScore+$roleScore+$modalityScore+$locationScore+$experienceScore+$educationScore);$strengths=[];$gaps=[];if($matched->isNotEmpty())$strengths[]='Coinciden habilidades: '.$matched->take(6)->join(', ').'.';else$gaps[]='No se detectaron habilidades coincidentes de forma explícita.';if($roleScore)$strengths[]='El titular profesional se relaciona con la vacante.';else$gaps[]='El titular profesional no refleja claramente este puesto.';if(!$modalityScore)$gaps[]='La modalidad no coincide con las preferencias indicadas.';if(!$locationScore)$gaps[]='La ubicación no coincide con las provincias preferidas.';return['score'=>$score,'level'=>$score>=75?'alta':($score>=50?'media':'baja'),'strengths'=>$strengths,'gaps'=>$gaps,'disclaimer'=>'Compatibilidad asistida y explicable. No decide ni rechaza candidaturas automáticamente.'];}}
